def compute(vars):
    net_profit = vars["v1"]
    attributable_net_profit = vars["v2"]

    if net_profit == 0:
        return None

    ratio = attributable_net_profit / net_profit

    return {
        "value": ratio,
        "trace": {
            "net_profit": net_profit,
            "attributable_net_profit": attributable_net_profit,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
